"""Authored bilingual source families. All people and organizations are synthetic.
Each translated pair shares a family and split; no translation crosses a split.
"""
SEEDS=[]
def add(domain,split,gold,ko,en):
    SEEDS.append(dict(domain=domain,split=split,gold=gold,ko=ko,en=en,family=f'{domain}-{split}-{sum(s["domain"]==domain and s["split"]==split for s in SEEDS):02d}'))

def build():
 SEEDS.clear()
 # Customer records: individual records, rather than mere discussion of data protection.
 d='customer_records';s='train'
 add(d,s,'match','{person} 고객은 {product}를 {qty}개 구매했고 대금 {money}만원 중 {small}만원이 미납이다.','Customer {person} purchased {qty} units of {product}; {small} of the {money} dollar invoice remains unpaid.')
 add(d,s,'match','배송 처리표\n성명: {person}\n주문: {product}\n배송 변경 요청: 자택 수령에서 직장 수령으로 변경.','Fulfilment row\nName: {person}\nOrder: {product}\nService request: change delivery from home to the office.')
 add(d,s,'match','{person}의 고객 계정에서 이번 달 결제 실패 {qty}건을 확인했다. 담당자는 다음 청구 전 연락할 것.','The customer account of {person} has {qty} failed payments this month. Contact them before the next billing attempt.')
 add(d,s,'match','고객별 지원 이력: {person} — {product} 고장으로 {qty}회 교환. 환급 예정액 {small}만원.','Individual support history: {person} — {qty} replacements of {product}; refund due: ${small}.')
 add(d,s,'match','{person} / 이용 상품 {product} / 누적 사용료 {money}만원 / 납부일 {day}일.','{person} / subscription {product} / accumulated usage charge ${money} / payment date day {day}.')
 add(d,s,'match','CRM 메모: {person}에게 지난 구매 불만을 사유로 다음 주문에만 적용되는 보상 포인트 {qty}점을 지급했다.','CRM note: {person} received {qty} goodwill points for dissatisfaction with their previous purchase, usable on their next order.')
 add(d,s,'match','반품 정산 — 구매자 {person}, 품목 {product}, 반품 사유 오배송, 환불 처리 대기.','Return settlement — buyer {person}, item {product}, reason wrong delivery, refund pending.')
 add(d,s,'match','상담 기록의 주체는 {person}이다. 지난주 {product} 계약을 해지했고 남은 이용료를 분할 납부하기로 했다.','This support record concerns {person}. They cancelled {product} last week and arranged instalments for the remaining service charge.')
 add(d,s,'no_match','이번 달 {product} 전체 판매 수량은 {qty}개다. 개인 이름이나 개별 주문은 포함하지 않은 상품군 집계다.','The aggregate monthly sales count for {product} is {qty}. This product-category summary has no names or individual orders.')
 add(d,s,'no_match','고객 관리 교육: 개인별 구매 내역과 결제 잔액은 접근 권한이 있는 담당자만 조회한다. 실제 고객 기록은 이 안내에 없다.','Customer-management training: restrict access to purchase histories and outstanding balances. This guidance contains no populated customer records.')
 add(d,s,'no_match','빈 주문 양식: 고객명 [입력], 구매품 [입력], 결제금액 [입력].','Blank order form: customer name [enter], item [enter], amount [enter].')
 add(d,s,'no_match','{person}은 공개 제품 설명회 발표자다. 발표 주제는 {product} 사용법이며 고객 계정 정보는 제시하지 않는다.','{person} is the speaker at a public product demonstration about using {product}; no customer account details are supplied.')
 add(d,s,'no_match','서비스 품질 지표: 평균 응답 시간 {small}분, 전체 만족도 {rate}%. 개인별 상담 이력은 제외했다.','Service-quality aggregates: average response time {small} minutes, satisfaction {rate}%; individual case histories are excluded.')
 add(d,s,'no_match','{product} 공개 사용설명서: 전원을 연결한 뒤 설정 메뉴를 연다. 고장 시 공식 지원 창구를 이용한다.','Public {product} manual: connect power, open settings, and contact the official support desk for faults.')
 add(d,s,'insufficient','첨부한 고객별 거래표를 검토해야 하지만 본문에는 표가 없고 미리보기도 실패했다.','The customer transaction attachment must be reviewed, but its table is absent and the preview failed.')
 add(d,s,'insufficient','고객 데이터 파일의 내용이 암호화되어 읽히지 않는다. 현재 보이는 것은 파일 존재 여부뿐이다.','The customer data file is encrypted and unreadable. Only the existence of the file is visible.')
 add(d,s,'insufficient','열 제목 일부만 추출됨: 대상 | 내역 | 금액. 데이터 행이 잘려 실제 개인 기록인지 알 수 없다.','Only partial column headings were extracted: subject | details | amount. Data rows are cut off, so individual records cannot be assessed.')
 add(d,s,'insufficient','구매 이력 이미지가 흐려 이름과 기록을 읽을 수 없다. 원본 확인이 필요하다.','The purchase-history image is too blurred to read names or records; the original is needed.')
 s='dev'
 add(d,s,'match','멤버십 담당 인계: {person}의 월 이용료 {money}만원을 중복 청구하여 차액 반환을 진행한다.','Membership handover: {person} was double charged a ${money} monthly fee; arrange reimbursement.')
 add(d,s,'match','{person}의 구매품 {product}는 보증 수리 중이다. 이번 방문은 올해 {qty}번째 접수다.','{person} has {product} under warranty repair; this is their {qty}th case this year.')
 add(d,s,'match','거래원장 개인 행: {person}; 대여 장비 {product}; 연체일 {day}; 미수금 {small}만원.','Individual ledger row: {person}; rented equipment {product}; overdue days {day}; receivable ${small}.')
